// G2-U1 Scratch lessons that run on the real Scratch VM (scratch-g2 lab).
// Each lesson owns: its new concept, a story, a prediction, two hands-on
// practices with different skill goals, one real error/boundary case with
// three hint layers, a bounded creative change and the project limits. The
// matching .sb3 sample and sandbox model are generated by
// examples/scratch/g2/build_g2_projects.py. Nothing here is a published
// course or a verified grade.

export type G2Field = 'X' | 'Y' | 'MESSAGE' | 'COSTUME' | 'TIMES' | 'DURATION' | 'BACKDROP' | 'SOUND_MENU' | 'DIRECTION' | 'STEPS' | 'DEGREES' | 'BROADCAST_OPTION'
export type G2Slot = { key: string; field: G2Field; label: string; min?: number; max?: number; maxLength?: number; options?: string[]; tenths?: boolean }
export type G2BlockType = 'kc2_goto' | 'kc2_say' | 'kc2_switch_costume' | 'kc2_repeat' | 'kc2_next_costume' | 'kc2_wait' | 'kc2_switch_backdrop' | 'kc2_play_sound'
  | 'kc2_goto_start' | 'kc2_point_direction' | 'kc2_move_steps' | 'kc2_turn_right' | 'kc2_broadcast'
/** `fixed` shows a value the lesson keeps fixed (its field is shown but locked in the editor). */
export type G2BlockSpec = { type: G2BlockType; vmBlock: string; slots: G2Slot[]; children?: G2BlockSpec[]; fixed?: Partial<Record<G2Field, string>> }
export type G2ScriptSpec = {
  hat: 'kc2_flag' | 'kc2_clicked' | 'kc2_when_receive'
  body: G2BlockSpec[]
  /** Editable fields on the hat itself (the message a "when I receive" hat listens for). */
  hatSlots?: G2Slot[]
  hatFixed?: Partial<Record<G2Field, string>>
}
export type G2TargetSpec = {
  name: string
  kind: 'stage' | 'sprite'
  label: string
  scripts: G2ScriptSpec[]
  /** Costume (stage: backdrop) names offered by this target's costume/backdrop dropdowns. */
  costumes?: string[]
  /** Sound names offered by this target's sound dropdowns. */
  sounds?: string[]
  /** Broadcast message names offered by this target's message dropdowns. */
  messages?: string[]
  /** Blocks offered in the toolbox beyond the target's own scripts (used for the stage error cases). */
  extraToolbox?: Array<'kc2_goto' | 'kc2_switch_costume'>
}
export type G2Task = { id: 'practiceA' | 'practiceB' | 'debug' | 'create'; title: string; goal: string; how: string; skill: string }
export type G2Step = { id: string; solutions: string[]; counterExamples: string[] }
export type G2Lesson = {
  id: string
  title: string
  concept: string
  /** Base64 text of the genuine sample .sb3 (decoded to the same zip bytes before the VM loads it). */
  sample: string
  exportName: string
  story: string
  conceptExplain: string[]
  predict: { question: string; options: string[]; correct: string; explain: string }
  tasks: G2Task[]
  hints: [string, string, string]
  reflection: string[]
  limitations: string[]
  targets: G2TargetSpec[]
  steps: G2Step[]
  nextLesson: string
  /** Show each sprite's VM direction in the observation panel (motion lessons). */
  showDirection?: boolean
}

export type G2Point = { x: number; y: number }
export const BIRD_NEST_ZONE = { minX: 80, maxX: 150, minY: 45, maxY: 95 } as const
export const DEFAULT_CAT_GREETING = '你好！我是小橘猫。'

const coord = (target: string, block: string): G2Slot[] => [
  { key: `${target}|${block}|X`, field: 'X', label: 'x', min: -240, max: 240 },
  { key: `${target}|${block}|Y`, field: 'Y', label: 'y', min: -180, max: 180 },
]
const say = (target: string, block: string): G2Slot[] => [
  { key: `${target}|${block}|MESSAGE`, field: 'MESSAGE', label: '说的话', maxLength: 20 },
]
const greetingSprite = (name: string, prefix: string): G2TargetSpec => ({
  name, kind: 'sprite', label: name,
  scripts: [
    { hat: 'kc2_flag', body: [{ type: 'kc2_goto', vmBlock: `${prefix}_goto`, slots: coord(name, `${prefix}_goto`) }] },
    { hat: 'kc2_clicked', body: [{ type: 'kc2_say', vmBlock: `${prefix}_say`, slots: say(name, `${prefix}_say`) }] },
  ],
})

