/** What the lab observed from the real VM (never from the editor alone). */
export type G2Observations = {
  /** Sprites whose own click script made them speak (VM SAY after a CLICK). */
  clickedSpeakers: string[]
  /** The VM reported a stage move attempt and the stage did not move. */
  stageMoveRejected: boolean
  /** Sprite positions from the VM after at least one green-flag run (null before any run). */
  positionsAfterRun: Record<string, G2Point> | null
  /** Latest text each sprite actually said in the VM. */
  lastSaid: Record<string, string>
  /** Sprite costumes from the VM after at least one green-flag run. */
  costumesAfterRun: Record<string, string> | null
  /** Most costume changes the VM showed during one click run, per sprite. */
  clickCostumeChanges: Record<string, number>
  /** First costume change seen after clicking each sprite. */
  firstClickTransition: Record<string, { from: string; to: string }>
  /** The VM ran "switch costume" on the stage and no target changed costume. */
  stageCostumeRejected: boolean
  /** Backdrop after a finished green-flag run, and how many times the stage's own sounds played in it (in run order). */
  flagRuns: Array<{ backdrop: string; stagePlays: number; positions?: Record<string, G2Point> }>
  /** Sounds each sprite played in the VM after being clicked. */
  clickSounds: Record<string, string[]>
  /** Total degrees each sprite really turned in the VM during each finished click run. */
  clickTurns: Record<string, number[]>
  /** Finished broadcast runs: the message the VM really sent, who spoke during the run, and the end state. */
  broadcastRuns: Array<{ message: string; speakers: string[]; backdrop: string; positions: Record<string, G2Point> }>
}

export const emptyG2Observations = (): G2Observations => ({
  clickedSpeakers: [], stageMoveRejected: false, positionsAfterRun: null, lastSaid: {},
  costumesAfterRun: null, clickCostumeChanges: {}, firstClickTransition: {}, stageCostumeRejected: false,
  flagRuns: [], clickSounds: {}, clickTurns: {}, broadcastRuns: [],
})

export function inBirdNest(point: G2Point | undefined | null): boolean {
  if (!point || !Number.isFinite(point.x) || !Number.isFinite(point.y)) return false
  return point.x >= BIRD_NEST_ZONE.minX && point.x <= BIRD_NEST_ZONE.maxX && point.y >= BIRD_NEST_ZONE.minY && point.y <= BIRD_NEST_ZONE.maxY
}

export type G2TaskState = Record<G2Task['id'], boolean>

export function evaluateG2U1L01(obs: G2Observations): G2TaskState {
  const said = new Set(obs.clickedSpeakers)
  const catText = obs.lastSaid['小橘猫']
  return {
    practiceA: said.has('小橘猫') && said.has('小鸟'),
    practiceB: inBirdNest(obs.positionsAfterRun?.['小鸟']),
    debug: obs.stageMoveRejected,
    create: said.has('小橘猫') && typeof catText === 'string' && catText.length > 0 && catText !== DEFAULT_CAT_GREETING,
  }
}

export function evaluateG2U1L02(obs: G2Observations): G2TaskState {
  return {
    practiceA: obs.costumesAfterRun?.['小橘猫'] === '挥手',
    practiceB: (obs.clickCostumeChanges['小橘猫'] ?? 0) >= 3,
    debug: obs.stageCostumeRejected,
    create: obs.costumesAfterRun?.['小鸟'] === '展翅',
  }
}

export function evaluateG2U1L03(obs: G2Observations): G2TaskState {
  const runs = obs.flagRuns
  const firstRepeat = runs.findIndex(r => r.stagePlays >= 2)
  const fixedAfter = firstRepeat >= 0 && runs.slice(firstRepeat + 1).some(r => r.stagePlays === 1)
  const said = obs.lastSaid['小橘猫']
  return {
    practiceA: runs.some(r => r.backdrop === '绿色草地'),
    practiceB: (obs.clickSounds['小鸟'] ?? []).includes('啾啾'),
    debug: fixedAfter,
    create: !!said && said !== L03_WELCOME && runs.some(r => r.backdrop === '绿色草地' && r.stagePlays === 1),
  }
}

export function evaluateG2U1L04(obs: G2Observations): G2TaskState {
  const catX = obs.flagRuns.map(r => r.positions?.['小橘猫']?.x).filter((x): x is number => typeof x === 'number')
  const firstLeft = catX.findIndex(x => x < L04_CAT_START.x)
  const turns = obs.clickTurns['风车'] ?? []
  const said = obs.lastSaid['小橘猫']
  const arrived = obs.flagRuns.some(r => inFishZone(r.positions?.['小橘猫']))
  return {
    practiceA: arrived,
    practiceB: turns.includes(90),
    debug: firstLeft >= 0 && catX.slice(firstLeft + 1).some(x => x > L04_CAT_START.x),
    create: turns.includes(360) && arrived && !!said && said !== L04_ARRIVAL,
  }
}

export function inCenterZone(point: G2Point | undefined | null): boolean {
  return !!point && Number.isFinite(point.x) && point.x >= L05_CENTER_ZONE.minX && point.x <= L05_CENTER_ZONE.maxX
}

export function evaluateG2U1L05(obs: G2Observations): G2TaskState {
  const runs = obs.broadcastRuns.filter(r => r.message === '开场')
  const firstSilent = runs.findIndex(r => !r.speakers.includes('小鸟'))
  const birdLine = obs.lastSaid['小鸟']
  return {
    practiceA: runs.some(r => r.backdrop === '灯光舞台'),
    practiceB: runs.some(r => inCenterZone(r.positions['小白兔'])),
    debug: firstSilent >= 0 && runs.slice(firstSilent + 1).some(r => r.speakers.includes('小鸟')),
    create: !!birdLine && birdLine !== L05_BIRD_LINE &&
      runs.some(r => r.speakers.includes('小鸟') && r.backdrop === '灯光舞台' && inCenterZone(r.positions['小白兔'])),
  }
}

/** What the VM actually showed for the lesson's prediction question (null until observed). */
export function observedPrediction(id: string, obs: G2Observations): string | null {
  if (id === g2u1L01.id) return obs.clickedSpeakers.includes('小鸟') ? '小鸟说话' : null
  if (id === g2u1L02.id) {
    const first = obs.firstClickTransition['小橘猫']
    if (!first || first.from !== '站立') return null
    return first.to === '挥手' ? '变成挥手' : '保持站立'
  }
  if (id === g2u1L03.id) {
    const first = obs.flagRuns[0]
    if (!first) return null
    return first.stagePlays === 1 ? '1 次' : first.stagePlays === 3 ? '3 次' : null
  }
  if (id === g2u1L04.id) {
    const x = obs.flagRuns[0]?.positions?.['小橘猫']?.x
    if (typeof x !== 'number' || x === L04_CAT_START.x) return null
    return x < L04_CAT_START.x ? '向左走' : '向右走'
  }
  if (id === g2u1L05.id) {
    const first = obs.broadcastRuns[0]
    if (!first) return null
    return first.speakers.includes('小鸟') ? '会说话' : '不会说话'
  }
  return null
}

export function evaluateG2Lesson(id: string, obs: G2Observations): G2TaskState | null {
  if (id === g2u1L01.id) return evaluateG2U1L01(obs)
  if (id === g2u1L02.id) return evaluateG2U1L02(obs)
  if (id === g2u1L03.id) return evaluateG2U1L03(obs)
  if (id === g2u1L04.id) return evaluateG2U1L04(obs)
  if (id === g2u1L05.id) return evaluateG2U1L05(obs)
  return null
}
